const fs = require('node:fs');
const path = require('node:path');
const destination = path.join(__dirname, '../src/generated/mapAssets.ts');
const js = fs.readFileSync(require.resolve('leaflet/dist/leaflet.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
const css = fs.readFileSync(require.resolve('leaflet/dist/leaflet.css'), 'utf8');
const license = fs.readFileSync(require.resolve('leaflet/LICENSE'), 'utf8');
fs.mkdirSync(path.dirname(destination), { recursive: true });
fs.writeFileSync(destination, `// Generated by scripts/build-map-assets.cjs; do not edit.\nexport const leafletJs = ${JSON.stringify(`/* ${license} */\n${js}`)};\nexport const leafletCss = ${JSON.stringify(css)};\n`);
